import{f as t,c as e,o,a5 as r}from"./chunks/framework.BsEAYNxL.js";const p=JSON.parse('{"title":"AI 编年史 07：推理 (Reasoning) 的慢思考","description":"","frontmatter":{"title":"AI 编年史 07：推理 (Reasoning) 的慢思考","date":"2026-02-14T00:00:00.000Z","categories":["AI","Tech History"],"tags":["Reasoning","CoT","o1","AlphaGeometry","System 2","Chronicle"],"ai_role":"writer","reading_stats":{"count":945,"minutes":3}},"headers":[],"relativePath":"ai-chronicles/08-reasoning.md","filePath":"ai-chronicles/08-reasoning.md","lastUpdated":null}'),n={name:"ai-chronicles/08-reasoning.md"};function s(i,a,l,h,g,c){return o(),e("div",null,[...a[0]||(a[0]=[r('<h2 id="_0-核心工程直觉-用时间换智能-test-time-compute" tabindex="-1">0. 核心工程直觉：用时间换智能 (Test-time Compute) <a class="header-anchor" href="#_0-核心工程直觉-用时间换智能-test-time-compute" aria-label="Permalink to &quot;0. 核心工程直觉：用时间换智能 (Test-time Compute)&quot;">​</a></h2><p>如果说 Pre-training 是“读万卷书”（用海量数据换智能），那么 Reasoning 就是“行万里路”（用推理时间换智能）。</p><ul><li><strong>System 1 (直觉)</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><mn>1</mn><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord">1</span><span class="mclose">)</span></span></span></span> 复杂度。看到 <code>1+1</code> 直接输出 <code>2</code>。靠的是记忆和统计相关性。</li><li><strong>System 2 (推理)</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><mi>N</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(N)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span><span class="mclose">)</span></span></span></span> 甚至指数级复杂度。看到复杂数学题，不能马上输出，而是要<strong>搜索</strong>、<strong>试错</strong>、<strong>回溯</strong>。</li></ul><p>工程上，o1 的本质就是把 <strong>MCTS (蒙特卡洛树搜索)</strong> 或类似的搜索过程内化到了模型的前向传播里。</p><h2 id="第一阶段-next-token-prediction-——-直觉反应-pre-2022" tabindex="-1">第一阶段：Next Token Prediction —— 直觉反应 (Pre-2022) <a class="header-anchor" href="#第一阶段-next-token-prediction-——-直觉反应-pre-2022" aria-label="Permalink to &quot;第一阶段：Next Token Prediction —— 直觉反应 (Pre-2022)&quot;">​</a></h2><p>GPT-3 就像是一个拥有无限直觉的天才。</p><h3 id="_1-1-特点" tabindex="-1">1.1 特点 <a class="header-anchor" href="#_1-1-特点" aria-label="Permalink to &quot;1.1 特点&quot;">​</a></h3><ul><li><strong>System 1 (快思考)</strong>：卡尼曼《思考，快与慢》里的直觉系统。</li><li><strong>痛点</strong>：对于逻辑链很长的问题（如数学证明、复杂推理），经常一本正经地胡说八道。</li><li><strong>原因</strong>：它在生成每一个字时，并没有规划整个句子，也没有回溯检查。</li></ul><h2 id="第二阶段-cot-chain-of-thought-——-思维显性化-2022" tabindex="-1">第二阶段：CoT (Chain-of-Thought) —— 思维显性化 (2022) <a class="header-anchor" href="#第二阶段-cot-chain-of-thought-——-思维显性化-2022" aria-label="Permalink to &quot;第二阶段：CoT (Chain-of-Thought) —— 思维显性化 (2022)&quot;">​</a></h2><p>Google 的一项简单发现改变了游戏规则。</p><h3 id="_2-1-核心思想" tabindex="-1">2.1 核心思想 <a class="header-anchor" href="#_2-1-核心思想" aria-label="Permalink to &quot;2.1 核心思想&quot;">​</a></h3><ul><li><strong>Prompt</strong>：只要加上一句话 &quot;Let&#39;s think step by step&quot; (让我们一步步思考)。</li><li><strong>效果</strong>：模型会自动生成中间推理步骤，准确率飙升。</li><li><strong>本质</strong>：通过延长生成的 Token 序列，给模型更多的时间去“计算”。每个 Token 都是一次 Transformer 的前向传播。</li><li><strong>论文</strong>：<strong><a href="https://arxiv.org/abs/2201.11903" target="_blank" rel="noreferrer">Chain-of-Thought Prompting Elicits Reasoning in Large Language Models (2022)</a></strong></li></ul><h3 id="_2-2-变体" tabindex="-1">2.2 变体 <a class="header-anchor" href="#_2-2-变体" aria-label="Permalink to &quot;2.2 变体&quot;">​</a></h3><ul><li><strong>Few-Shot CoT</strong>：给几个带有推理步骤的例子。</li><li><strong>Zero-Shot CoT</strong>：直接加 Prompt。</li></ul><h2 id="第三阶段-tot-tree-of-thoughts-——-搜索与回溯-2023" tabindex="-1">第三阶段：ToT (Tree of Thoughts) —— 搜索与回溯 (2023) <a class="header-anchor" href="#第三阶段-tot-tree-of-thoughts-——-搜索与回溯-2023" aria-label="Permalink to &quot;第三阶段：ToT (Tree of Thoughts) —— 搜索与回溯 (2023)&quot;">​</a></h2><p>CoT 是线性的，但真正的思考往往是树状的。</p><h3 id="_3-1-核心思想" tabindex="-1">3.1 核心思想 <a class="header-anchor" href="#_3-1-核心思想" aria-label="Permalink to &quot;3.1 核心思想&quot;">​</a></h3><ul><li><strong><a href="https://arxiv.org/abs/2305.10601" target="_blank" rel="noreferrer">ToT (Tree of Thoughts, 2023)</a></strong>：让模型生成多个可能的下一步思路 (Branching)。</li><li><strong>Evaluation</strong>：自我评估每条思路的可行性。</li><li><strong>Backtracking</strong>：如果走不通，就回溯，换一条路走。</li><li><strong>本质</strong>：把大模型变成了搜索引擎 (MCTS, BFS/DFS)。</li></ul><h3 id="_3-2-局限性" tabindex="-1">3.2 局限性 <a class="header-anchor" href="#_3-2-局限性" aria-label="Permalink to &quot;3.2 局限性&quot;">​</a></h3><ul><li>需要外部代码控制流程（比如 Python 脚本调用 API），模型本身并没有内化这种能力。</li></ul><h2 id="第四阶段-process-reward-model-——-过程监督-2023-2024" tabindex="-1">第四阶段：Process Reward Model —— 过程监督 (2023 - 2024) <a class="header-anchor" href="#第四阶段-process-reward-model-——-过程监督-2023-2024" aria-label="Permalink to &quot;第四阶段：Process Reward Model —— 过程监督 (2023 - 2024)&quot;">​</a></h2><p>OpenAI 发现，仅仅给最终答案打分是不够的。</p><h3 id="_4-1-核心思想" tabindex="-1">4.1 核心思想 <a class="header-anchor" href="#_4-1-核心思想" aria-label="Permalink to &quot;4.1 核心思想&quot;">​</a></h3><ul><li><strong>ORM (Outcome Reward Model)</strong>：只看结果对不对。容易导致模型为了得高分而编造错误的推理过程 (Hack)。</li><li><strong>PRM (Process Reward Model)</strong>：对每一个推理步骤打分。</li><li><strong>Let&#39;s Verify Step by Step</strong>：<strong><a href="https://arxiv.org/abs/2305.20050" target="_blank" rel="noreferrer">OpenAI 的数学论文 (2023)</a></strong> 证明，PRM 能显著提升数学解题能力。</li></ul><h2 id="第五阶段-o1-strawberry-——-真正的慢思考-2024" tabindex="-1">第五阶段：o1 (Strawberry) —— 真正的慢思考 (2024) <a class="header-anchor" href="#第五阶段-o1-strawberry-——-真正的慢思考-2024" aria-label="Permalink to &quot;第五阶段：o1 (Strawberry) —— 真正的慢思考 (2024)&quot;">​</a></h2><p>OpenAI 发布 <strong><a href="https://openai.com/index/learning-to-reason-with-llms/" target="_blank" rel="noreferrer">o1-preview</a></strong>，标志着推理模型的新纪元。</p><h3 id="_5-1-核心思想" tabindex="-1">5.1 核心思想 <a class="header-anchor" href="#_5-1-核心思想" aria-label="Permalink to &quot;5.1 核心思想&quot;">​</a></h3><ul><li><strong>Hidden CoT</strong>：模型在输出给用户之前，会在内部进行大量的“思考”。用户看不到这些思考过程（为了安全和商业机密），只看到最终结果。</li><li><strong>RL on Reasoning</strong>：使用强化学习专门训练模型的推理能力。让模型学会： <ul><li>拆解问题。</li><li>发现错误并自我修正。</li><li>尝试不同的策略。</li></ul></li><li><strong>Inference Scaling Laws</strong>：除了训练时的大力出奇迹，<strong>推理时的计算量</strong>也可以换取智能。思考时间越长，智力越高。</li></ul><h3 id="_5-2-意义" tabindex="-1">5.2 意义 <a class="header-anchor" href="#_5-2-意义" aria-label="Permalink to &quot;5.2 意义&quot;">​</a></h3><p>o1 在数学竞赛 (AIME) 和编程竞赛 (Codeforces) 中达到了人类顶尖水平。这标志着 AI 从“知识引擎”转向了“推理引擎”。 类似的还有 <strong><a href="https://www.nature.com/articles/s41586-023-06747-5" target="_blank" rel="noreferrer">AlphaGeometry (DeepMind, 2024)</a></strong>，专门解决奥数几何题。</p><h3 id="_5-3-总结" tabindex="-1">5.3 总结 <a class="header-anchor" href="#_5-3-总结" aria-label="Permalink to &quot;5.3 总结&quot;">​</a></h3><p>未来的 AI 将拥有两种模式：</p><ol><li><strong>快模式 (Turbo)</strong>：像 GPT-4o，秒回，用于日常对话。</li><li><strong>慢模式 (Reasoning)</strong>：像 o1，思考几分钟甚至几小时，用于解决科学难题。</li></ol>',33)])])}const d=t(n,[["render",s]]);export{p as __pageData,d as default};
